/* MediaPlayer: switch-based hierarchical state machine generated by MachinaState (C99). Do not edit by hand. */
#include "MediaPlayer.h"

/* Internal functions */
static size_t RegionOf(Demo_MediaPlayer_State state);
static size_t FirstRegionOf(Demo_MediaPlayer_State state);
static size_t RegionsOf(Demo_MediaPlayer_State state);
static void Trace(Demo_MediaPlayer* m, Demo_MediaPlayer_TraceKind kind, const char* name);
static void OnEntry(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void OnExit(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static Demo_MediaPlayer_State Innermost(const Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void ExitState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void EnterState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void EnterRegion(Demo_MediaPlayer* m, size_t region);
static void EnterDefault(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void EnterHistory(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, bool deep);
static void EnterDown(Demo_MediaPlayer* m, Demo_MediaPlayer_State from, Demo_MediaPlayer_State target, bool history);
static bool HandleEvent(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event);
static bool DispatchState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event);
static bool DispatchCore(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event);

static size_t RegionOf(Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Playing:
        case Demo_MediaPlayer_State_Paused:
            return 1;
        default:
            return 0;
    }
}

static size_t FirstRegionOf(Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Active:
            return 1;
        default:
            return 0;
    }
}

static size_t RegionsOf(Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Active:
            return 1;
        default:
            return 0;
    }
}

Demo_MediaPlayer_State Demo_MediaPlayer_ParentOf(Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Playing:
        case Demo_MediaPlayer_State_Paused:
            return Demo_MediaPlayer_State_Active;
        default:
            return Demo_MediaPlayer_State_None;
    }
}

const char* Demo_MediaPlayer_StateName(Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Stopped:
            return "Stopped";
        case Demo_MediaPlayer_State_Active:
            return "Active";
        case Demo_MediaPlayer_State_Playing:
            return "Playing";
        case Demo_MediaPlayer_State_Paused:
            return "Paused";
        case Demo_MediaPlayer_State_Ejected:
            return "Ejected";
        default:
            return "None";
    }
}

const char* Demo_MediaPlayer_EventName(Demo_MediaPlayer_Event event) {
    switch (event) {
        case Demo_MediaPlayer_Event_Play:
            return "Play";
        case Demo_MediaPlayer_Event_Pause:
            return "Pause";
        case Demo_MediaPlayer_Event_Stop:
            return "Stop";
        case Demo_MediaPlayer_Event_TrackEnd:
            return "TrackEnd";
        case Demo_MediaPlayer_Event_Eject:
            return "Eject";
        case Demo_MediaPlayer_Event_Resume:
            return "Resume";
        case Demo_MediaPlayer_Event_Volume:
            return "Volume";
        default:
            return "";
    }
}

static void Trace(Demo_MediaPlayer* m, Demo_MediaPlayer_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

static void OnEntry(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Active:
            m->hooks->powerOnAmp(m->context);
            break;
        case Demo_MediaPlayer_State_Playing:
            m->hooks->startPlayback(m->context);
            break;
        default:
            break;
    }
}

static void OnExit(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    switch (state) {
        case Demo_MediaPlayer_State_Active:
            m->hooks->powerOffAmp(m->context);
            break;
        case Demo_MediaPlayer_State_Playing:
            m->hooks->stopPlayback(m->context);
            break;
        default:
            break;
    }
}

static Demo_MediaPlayer_State Innermost(const Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    while (state != Demo_MediaPlayer_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Demo_MediaPlayer_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void ExitState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Demo_MediaPlayer_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Demo_MediaPlayer_Trace_Exit, Demo_MediaPlayer_StateName(state));
    OnExit(m, state);
    m->active[RegionOf(state)] = Demo_MediaPlayer_State_None;
    m->history[RegionOf(state)] = state;
}

static void EnterState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Demo_MediaPlayer_Trace_Enter, Demo_MediaPlayer_StateName(state));
    OnEntry(m, state);
}

static void EnterRegion(Demo_MediaPlayer* m, size_t region) {
    switch (region) {
        case 1:
            EnterDown(m, Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_Playing, false);
            break;
        default:
            break;
    }
}

static void EnterDefault(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
}

static void EnterHistory(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, bool deep) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        const Demo_MediaPlayer_State remembered = m->history[region];
        if (remembered == Demo_MediaPlayer_State_None) {
            EnterRegion(m, region);
        } else if (deep) {
            EnterState(m, remembered);
            EnterHistory(m, remembered, true);
        } else {
            EnterDown(m, state, remembered, false);
        }
    }
}

static void EnterDown(Demo_MediaPlayer* m, Demo_MediaPlayer_State from, Demo_MediaPlayer_State target, bool history) {
    Demo_MediaPlayer_State state = target;
    Demo_MediaPlayer_State next = Demo_MediaPlayer_State_None;
    while (Demo_MediaPlayer_ParentOf(state) != from) {
        next = state;
        state = Demo_MediaPlayer_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Demo_MediaPlayer_State_None) {
        if (history) {
            EnterHistory(m, state, false);
            return;
        }
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target, history);
}

static bool HandleEvent(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event) {
    switch (state) {
        case Demo_MediaPlayer_State_Stopped:
            switch (event) {
                case Demo_MediaPlayer_Event_Play:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Stopped -> Active");
                    ExitState(m, Demo_MediaPlayer_State_Stopped);
                    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Active, false);
                    return true;
                case Demo_MediaPlayer_Event_Eject:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Stopped -> Ejected");
                    ExitState(m, Demo_MediaPlayer_State_Stopped);
                    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Ejected, false);
                    return true;
                case Demo_MediaPlayer_Event_Resume:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Stopped -> Active (history)");
                    ExitState(m, Demo_MediaPlayer_State_Stopped);
                    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Active, true);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_MediaPlayer_State_Active:
            switch (event) {
                case Demo_MediaPlayer_Event_Stop:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Active -> Stopped");
                    ExitState(m, Demo_MediaPlayer_State_Active);
                    m->hooks->resetPosition(m->context);
                    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Stopped, false);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_MediaPlayer_State_Playing:
            switch (event) {
                case Demo_MediaPlayer_Event_Pause:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Playing -> Paused");
                    ExitState(m, Demo_MediaPlayer_State_Playing);
                    EnterDown(m, Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_Paused, false);
                    return true;
                case Demo_MediaPlayer_Event_TrackEnd:
                    if (m->hooks->hasNextTrack(m->context)) {
                        Trace(m, Demo_MediaPlayer_Trace_Transition, "Playing -> Playing");
                        ExitState(m, Demo_MediaPlayer_State_Playing);
                        m->hooks->nextTrack(m->context);
                        EnterDown(m, Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_Playing, false);
                        return true;
                    }
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Playing -> Stopped");
                    ExitState(m, Demo_MediaPlayer_State_Active);
                    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Stopped, false);
                    return true;
                case Demo_MediaPlayer_Event_Volume:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Playing (internal)");
                    m->hooks->setVolume(m->context, ((const Demo_MediaPlayer_VolumeArgs*)m->args)->level);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_MediaPlayer_State_Paused:
            switch (event) {
                case Demo_MediaPlayer_Event_Play:
                    Trace(m, Demo_MediaPlayer_Trace_Transition, "Paused -> Playing");
                    ExitState(m, Demo_MediaPlayer_State_Paused);
                    EnterDown(m, Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_Playing, false);
                    return true;
                default:
                    break;
            }
            break;
        default:
            break;
    }
    return false;
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Demo_MediaPlayer_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event) {
    Trace(m, Demo_MediaPlayer_Trace_Event, Demo_MediaPlayer_EventName(event));
    if (m->active[0] != Demo_MediaPlayer_State_None && DispatchState(m, m->active[0], event)) {
        return true;
    }
    Trace(m, Demo_MediaPlayer_Trace_Ignored, Demo_MediaPlayer_EventName(event));
    return false;
}

void Demo_MediaPlayer_Init(Demo_MediaPlayer* m, const Demo_MediaPlayer_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Demo_MediaPlayer_RegionCount; ++i) {
        m->active[i] = Demo_MediaPlayer_State_None;
        m->history[i] = Demo_MediaPlayer_State_None;
    }
    m->args = NULL;
}

void Demo_MediaPlayer_Start(Demo_MediaPlayer* m) {
    size_t i;
    for (i = 0; i < Demo_MediaPlayer_RegionCount; ++i) {
        m->active[i] = Demo_MediaPlayer_State_None;
        m->history[i] = Demo_MediaPlayer_State_None;
    }
    Trace(m, Demo_MediaPlayer_Trace_Start, "MediaPlayer");
    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Stopped, false);
}

bool Demo_MediaPlayer_Dispatch(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event) {
    bool handled = false;
    if (event != Demo_MediaPlayer_Event_Volume) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
    }
    return handled;
}

bool Demo_MediaPlayer_DispatchVolume(Demo_MediaPlayer* m, int level) {
    bool handled;
    Demo_MediaPlayer_VolumeArgs args;
    args.level = level;
    m->args = &args;
    handled = DispatchCore(m, Demo_MediaPlayer_Event_Volume);
    m->args = NULL;
    return handled;
}

Demo_MediaPlayer_State Demo_MediaPlayer_Current(const Demo_MediaPlayer* m) {
    return Innermost(m, m->active[0]);
}

bool Demo_MediaPlayer_IsIn(const Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    return state != Demo_MediaPlayer_State_None && m->active[RegionOf(state)] == state;
}

bool Demo_MediaPlayer_IsFinished(const Demo_MediaPlayer* m) {
    return m->active[0] == Demo_MediaPlayer_State_Ejected;
}

